    const next = () => {
      index += 1;
      if (index >= argv.length) {
        throw new Error(`missing value for ${arg}`);
      }
      return argv[index];
    };
    if (arg === "--report-dir") {
      options.reportDirs.push(next());
    } else if (arg === "--require") {
      options.requiredScenarios.push(next());
    } else if (arg === "--json-out") {
