public struct ArchiveSnapshot: Equatable, Sendable {
    public let hosts: [DockHostViewModel]
    public let hostStates: [DockHostStateViewModel]
    public let hostIdentityResolver: DockHostIdentityResolver
    public let sections: [DockSectionViewModel]

    public var rowCount: Int {
        sections.reduce(0) { count, section in
            count + section.rows.count
        }
    }

    public var unavailableMessage: String? {
        guard !hostStates.isEmpty,
              hostStates.allSatisfy(\.status.isUnavailable) else {
            return nil
        }
        return hostStates.map { "\($0.host.displayName): \($0.status.unavailableMessage ?? $0.status.subtitle)" }
            .joined(separator: "; ")
    }
}

public enum ArchiveStoreState: Equatable, Sendable {
    case configurationError(String)
    case idle([DockHostViewModel])
    case loading([DockHostViewModel])
    case loaded(ArchiveSnapshot)
    case empty(ArchiveSnapshot)
    case unavailable(ArchiveSnapshot, String)
}

public enum ArchiveRestoreRowStatus: Equatable, Sendable {
    case restored
    case failed(String)
    case skipped
}

public struct ArchiveRestoreResult: Equatable, Sendable {
    public let row: DockRowViewModel
    public let status: ArchiveRestoreRowStatus

    public init(row: DockRowViewModel, status: ArchiveRestoreRowStatus) {
        self.row = row
        self.status = status
    }
}

@MainActor
public final class ArchiveStore: ObservableObject {
    @Published public private(set) var state: ArchiveStoreState
    @Published public private(set) var actionError: String?

    public let screenStore: ArchiveScreenStore

    private var hosts: [DockHostConfiguration]
    private let commandEngine: ClientCommandEngine
    private var dataEngine: ArchiveDataEngine?
    private var isLoading = false
    private weak var connectivityReporter: (any AppConnectivityReporting)?
    private let connectivityEventSink: ConnectivityEventSink?

    public init(
        registry: HostRegistry,
        streamClient: any ThreadCardStreamConnecting = AppServerThreadCardStreamClient(view: .archive),
        archiver: any ThreadArchiveCommanding = AppServerThreadCommandClient(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore(),
        connectivityEventSink: ConnectivityEventSink? = nil,
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        self.hosts = registry.hosts
        self.commandEngine = ClientCommandEngine(archiver: archiver)
        self.connectivityEventSink = connectivityEventSink
        self.dataEngine = ArchiveDataEngine(
            registry: registry,
            streamClient: streamClient,
            metadataStore: metadataStore,
            now: now
        )
        let initialState = ArchiveStoreState.idle(registry.hosts.map(DockHostViewModel.init))
        self.state = initialState
        self.screenStore = ArchiveScreenStore(state: initialState)
    }

    public init(
        configurationError error: Error,
        archiver: any ThreadArchiveCommanding = AppServerThreadCommandClient(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore(),
        connectivityEventSink: ConnectivityEventSink? = nil,
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        self.hosts = []
        self.commandEngine = ClientCommandEngine(archiver: archiver)
        self.connectivityEventSink = connectivityEventSink
        self.dataEngine = nil
        let initialState = ArchiveStoreState.configurationError(error.localizedDescription)
        self.state = initialState
        self.screenStore = ArchiveScreenStore(state: initialState)
    }

    public func updateRegistry(_ registry: HostRegistry) async {
        hosts = registry.hosts
        if let dataEngine {
            await dataEngine.updateRegistry(registry)
        }
        setActionError(nil)
        setState(.idle(registry.hosts.map(DockHostViewModel.init)))
        publishConnectivity(for: state)
        await reload(showLoading: true)
    }

    public func setConnectivityReporter(_ reporter: (any AppConnectivityReporting)?) {
        connectivityReporter = reporter
        guard connectivityEventSink == nil else {
            return
        }
        reporter?.reportArchiveState(state)
    }

    public func load() async {
        await reload(showLoading: true)
    }

    public func refresh() async {
        await reload(showLoading: false)
    }

    @discardableResult
    public func restore(_ row: DockRowViewModel) async -> Bool {
        let result = await restoreRow(row)
        switch result.status {
        case .restored:
            await refresh()
            return true
        case .failed:
            return false
        case .skipped:
            return false
        }
    }

    @discardableResult
    public func restoreRows(
        _ rows: [DockRowViewModel],
        shouldStop: @MainActor () -> Bool = { false },
        onProgress: @MainActor ([ArchiveRestoreResult]) -> Void = { _ in }
    ) async -> [ArchiveRestoreResult] {
        guard !rows.isEmpty else {
            return []
        }

        var didRestoreAnyRow = false
        var results: [ArchiveRestoreResult] = []
        for row in rows {
            if shouldStop() {
                results.append(ArchiveRestoreResult(row: row, status: .skipped))
                onProgress(results)
                continue
            }

            let result = await restoreRow(row)
            if case .restored = result.status {
                didRestoreAnyRow = true
            }
            results.append(result)
            onProgress(results)
        }

        if didRestoreAnyRow {
            await refresh()
        }
        return results
    }

    private func restoreRow(_ row: DockRowViewModel) async -> ArchiveRestoreResult {
        guard let host = hostConfiguration(for: row) else {
            DockLog.archive.error("archive restore skipped missing host_id=\(row.id.hostID, privacy: .public) thread_id=\(DockLog.publicID(row.id.threadID), privacy: .public)")
            let message = "Host \(row.id.hostID) is no longer configured."
            setActionError(message)
            return ArchiveRestoreResult(row: row, status: .failed(message))
        }

        do {
            DockLog.archive.notice("archive restore action started host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.id.threadID), privacy: .public)")
            try await commandEngine.unarchive(row, on: host)
            setActionError(nil)
            DockLog.archive.notice("archive restore action finished host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.id.threadID), privacy: .public)")
            return ArchiveRestoreResult(row: row, status: .restored)
        } catch {
            DockLog.archive.error("archive restore action failed host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.id.threadID), privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
            let message = error.localizedDescription
            setActionError(message)
            return ArchiveRestoreResult(row: row, status: .failed(message))
        }
    }

    public func hostConfiguration(for row: DockRowViewModel) -> DockHostConfiguration? {
        if case .loaded(let snapshot) = state,
           let resolved = snapshot.hostIdentityResolver.resolve(
               rowHostID: row.id.hostID,
               sourceConfiguredHostID: row.sourceHostID
           ) {
            return resolved.host
        }
        if case .empty(let snapshot) = state,
           let resolved = snapshot.hostIdentityResolver.resolve(
               rowHostID: row.id.hostID,
               sourceConfiguredHostID: row.sourceHostID
           ) {
            return resolved.host
        }
        if case .unavailable(let snapshot, _) = state,
           let resolved = snapshot.hostIdentityResolver.resolve(
               rowHostID: row.id.hostID,
               sourceConfiguredHostID: row.sourceHostID
           ) {
            return resolved.host
        }
        if let sourceHostID = row.sourceHostID,
           let host = hosts.first(where: { $0.id == sourceHostID }) {
            return host
        }
        return DockHostIdentityResolver(hosts: hosts)
            .resolve(rowHostID: row.id.hostID, sourceConfiguredHostID: row.sourceHostID)?
            .host
    }

    private func reload(showLoading: Bool) async {
        guard !hosts.isEmpty else {
            DockLog.archive.warning("archive reload skipped reason=no_hosts")
            return
        }
        guard !isLoading else {
            DockLog.archive.debug("archive reload skipped reason=already_loading")
            return
        }

        let startedAt = Date()
        let signpostState = DockSignpost.archive.beginInterval("archive.reload")
        DockLog.archive.notice("archive reload started hosts=\(self.hosts.count, privacy: .public) show_loading=\(showLoading, privacy: .public)")
        isLoading = true
        defer {
            DockSignpost.archive.endInterval("archive.reload", signpostState)
            isLoading = false
        }

        if showLoading {
            setState(.loading(hosts.map(DockHostViewModel.init)))
            publishConnectivity(for: state)
        }

        guard let dataEngine else {
            DockLog.archive.warning("archive reload skipped reason=no_data_engine")
            return
        }

        let snapshot = await dataEngine.loadSnapshot()
        if snapshot.rowCount == 0, let message = snapshot.unavailableMessage {
            setState(.unavailable(snapshot, message))
        } else {
            setState(snapshot.rowCount == 0 ? .empty(snapshot) : .loaded(snapshot))
        }
        publishConnectivity(for: state)
        DockLog.archive.notice("archive reload finished hosts=\(self.hosts.count, privacy: .public) rows=\(snapshot.rowCount, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
    }

    private func setState(_ state: ArchiveStoreState) {
        self.state = state
        screenStore.setState(state)
    }

    private func setActionError(_ message: String?) {
        actionError = message
        screenStore.setActionError(message)
    }

    private func publishConnectivity(for state: ArchiveStoreState) {
        if connectivityEventSink == nil {
            connectivityReporter?.reportArchiveState(state)
        }
        recordConnectivityFacts(for: state)
    }

    private func recordConnectivityFacts(for state: ArchiveStoreState) {
        guard let connectivityEventSink else {
            return
        }
        let events = connectivityEvents(for: state)
        guard !events.isEmpty else {
            return
        }
        Task {
            for event in events {
                await connectivityEventSink.record(event)
            }
        }
    }

    private func connectivityEvents(for state: ArchiveStoreState) -> [ConnectivityRuntimeEvent] {
        switch state {
        case .configurationError(let message):
            return [
                ConnectivityRuntimeEvent(
                    source: .archive,
                    hostID: nil,
                    route: "archive/configuration",
                    status: message,
                    phase: .configurationError(message)
                )
            ]
        case .idle(let hosts):
            return hosts.map { host in
                ConnectivityRuntimeEvent(
                    source: .archive,
                    hostID: host.id,
                    route: "archive",
                    status: "idle",
                    phase: .unknown
                )
            }
        case .loading(let hosts):
            return hosts.map { host in
                ConnectivityRuntimeEvent(
                    source: .archive,
                    hostID: host.id,
                    route: "archive/list",
                    status: "checking",
                    phase: .checking
                )
            }
        case .loaded(let snapshot), .empty(let snapshot), .unavailable(let snapshot, _):
            return snapshot.hostStates.map { hostState in
                ConnectivityRuntimeEvent(
                    source: .archive,
                    hostID: hostState.host.id,
                    route: "archive/list",
                    status: hostState.status.subtitle,
                    phase: Self.connectivityPhase(for: hostState.status)
                )
            }
        }
    }

    private nonisolated static func connectivityPhase(
        for status: DockHostLoadStatus
    ) -> HostConnectivityPhase {
        switch status {
        case .checking:
            return .checking
        case .loaded(let rowCount):
            return .online("\(rowCount) sessions")
        case .partial(_, let message):
            return .partial(message)
        case .empty:
            return .online("Online, no sessions")
        case .offline(let message):
            return .offline(message)
        case .error(let message):
            return .error(message)
        }
    }
}

import Foundation

struct ThreadCardSnapshotCollection: Equatable, Sendable {
    let hosts: [DockStreamHostDTO]
    let cards: [DockThreadCardDTO]
    let freshness: DockStreamFreshnessDTO?
    let isComplete: Bool

    var hostLoadStatus: DockHostLoadStatus {
        let hasUnprovenCard = cards.contains { card in
            card.freshness != .fresh || card.completeness != .complete
        }
        if !isComplete {
            return .partial(rowCount: cards.count, message: "Stream incomplete")
        }
        if hasUnprovenCard {
            return .partial(rowCount: cards.count, message: "Card truth incomplete")
        }
        switch freshness?.status {
        case .fresh:
            return cards.isEmpty ? .empty : .loaded(rowCount: cards.count)
        case .stale:
            return .partial(rowCount: cards.count, message: freshness?.lastError ?? "Stale card data")
        case .offline:
            return .partial(rowCount: cards.count, message: freshness?.lastError ?? "Offline card data")
        case .error:
            return .partial(rowCount: cards.count, message: freshness?.lastError ?? "Card stream error")
        case .unknown, nil:
            return .partial(rowCount: cards.count, message: "Unknown card freshness")
        }
    }
}

struct ThreadCardStreamSnapshotCollector: Sendable {
    let expectedView: ThreadCardStreamView
    let timeout: Duration

    init(
        expectedView: ThreadCardStreamView,
        timeout: Duration = CodexDockConstants.AppServer.defaultRequestTimeout
    ) {
        self.expectedView = expectedView
        self.timeout = timeout
    }

    func collect(from connection: any ThreadCardStreamConnection) async throws -> ThreadCardSnapshotCollection {
        try await withThrowingTaskGroup(of: ThreadCardSnapshotCollection.self) { group in
            group.addTask {
                try await collectWithoutTimeout(from: connection, expectedView: expectedView)
            }
            group.addTask {
                try await Task.sleep(for: timeout)
                throw DockRequestFailure.error("Timed out waiting for \(expectedView.rawValue) card stream to complete")
            }

            guard let collection = try await group.next() else {
                throw DockRequestFailure.error("Card stream ended before returning a snapshot")
            }
            group.cancelAll()
            return collection
        }
    }
}

private func collectWithoutTimeout(
    from connection: any ThreadCardStreamConnection,
    expectedView: ThreadCardStreamView
) async throws -> ThreadCardSnapshotCollection {
    var hostsByID: [String: DockStreamHostDTO] = [:]
    var cardsByID: [String: DockThreadCardDTO] = [:]
    let snapshot = try await connection.subscribe()
    try apply(
        snapshot,
        expectedView: expectedView,
        hostsByID: &hostsByID,
        cardsByID: &cardsByID
    )
    if let completion = completionState(snapshot) {
        return collection(
            hostsByID: hostsByID,
            cardsByID: cardsByID,
            freshness: snapshot.freshness,
            completion: completion
        )
    }

    for try await update in connection.updates() {
        try apply(
            update,
            expectedView: expectedView,
            hostsByID: &hostsByID,
            cardsByID: &cardsByID
        )
        if let completion = completionState(update) {
            return collection(
                hostsByID: hostsByID,
                cardsByID: cardsByID,
                freshness: update.freshness,
                completion: completion
            )
        }
    }

    throw DockRequestFailure.error("Card stream closed before \(expectedView.rawValue) snapshot completed")
}

private func apply(
    _ update: ThreadCardStreamUpdateDTO,
    expectedView: ThreadCardStreamView,
    hostsByID: inout [String: DockStreamHostDTO],
    cardsByID: inout [String: DockThreadCardDTO]
) throws {
    guard update.schemaVersion == CodexDockConstants.Dock.streamSchemaVersion,
          update.view == expectedView else {
        throw DockRequestFailure.error("Unexpected \(expectedView.rawValue) card stream contract")
    }

    switch update.kind {
    case .snapshot:
        hostsByID = Dictionary(uniqueKeysWithValues: (update.hosts ?? []).map { ($0.id, $0) })
        cardsByID = Dictionary(uniqueKeysWithValues: (update.cards ?? [])
            .filter(\.isAppFacingHumanThreadCard)
            .map { ($0.id, $0) })
    case .delta:
        for host in update.upsertHosts ?? [] {
            hostsByID[host.id] = host
        }
        for card in (update.upsertCards ?? []).filter(\.isAppFacingHumanThreadCard) {
            cardsByID[card.id] = card
        }
        for cardID in update.deleteCardIDs ?? [] {
            cardsByID.removeValue(forKey: cardID)
        }
    case .heartbeat:
        break
    }
}

private func sortedHosts(_ hostsByID: [String: DockStreamHostDTO]) -> [DockStreamHostDTO] {
    hostsByID.values.sorted { lhs, rhs in
        lhs.id < rhs.id
    }
}

private enum StreamCompletionState {
    case complete
    case terminalIncomplete
}

private func completionState(_ update: ThreadCardStreamUpdateDTO) -> StreamCompletionState? {
    if update.complete == true {
        return .complete
    }
    guard update.window?.nextOffset == nil,
          update.totalRows != nil else {
        return nil
    }
    return .terminalIncomplete
}

private func collection(
    hostsByID: [String: DockStreamHostDTO],
    cardsByID: [String: DockThreadCardDTO],
    freshness: DockStreamFreshnessDTO?,
    completion: StreamCompletionState
) -> ThreadCardSnapshotCollection {
    ThreadCardSnapshotCollection(
        hosts: sortedHosts(hostsByID),
        cards: sortedCards(cardsByID),
        freshness: freshness,
        isComplete: completion == .complete
    )
}

private func sortedCards(_ cardsByID: [String: DockThreadCardDTO]) -> [DockThreadCardDTO] {
    cardsByID.values.sorted { lhs, rhs in
        if lhs.orderKey != rhs.orderKey {
            return lhs.orderKey < rhs.orderKey
        }
        return lhs.id < rhs.id
    }
}

import Foundation

public struct HostConnectionTestResult: Equatable, Sendable {
    public let rowCount: Int

    public init(rowCount: Int) {
        self.rowCount = rowCount
    }
}

public protocol HostConnectionTesting: Sendable {
    func testConnection(to host: DockHostConfiguration) async throws -> HostConnectionTestResult
}

public struct CardStreamHostConnectionTester: HostConnectionTesting {
    private let streamClient: any ThreadCardStreamConnecting

    public init(streamClient: any ThreadCardStreamConnecting = AppServerThreadCardStreamClient()) {
        self.streamClient = streamClient
    }

    public func testConnection(to host: DockHostConfiguration) async throws -> HostConnectionTestResult {
        var connection: (any ThreadCardStreamConnection)?
        do {
            connection = try await streamClient.connect(to: host)
            let snapshot = try await connection?.subscribe()
            await connection?.close()
            return HostConnectionTestResult(
                rowCount: snapshot?.totalRows ?? snapshot?.cards?.count ?? 0
            )
        } catch {
            await connection?.close()
            throw mapFailure(error)
        }
    }

    private func mapFailure(_ error: Error) -> DockRequestFailure {
        if let failure = error as? DockRequestFailure {
            return failure
        }
        if let clientError = error as? AppServerClientError {
            switch clientError {
            case .disconnected, .notConnected, .requestTimedOut, .transport:
                return .offline(clientError.localizedDescription)
            case .duplicateRequestID,
                 .malformedMessage,
                 .requestCancelled,
                 .responseDecoding,
                 .server,
                 .unexpectedServerRequest,
                 .unmatchedResponse:
                return .error(clientError.localizedDescription)
            }
        }
        return .error(error.localizedDescription)
    }
}

