import Foundation

actor ArchiveDataEngine {
    private var hosts: [DockHostConfiguration]
    private let streamClient: any ThreadCardStreamConnecting
    private let metadataEngine: LocalMetadataEngine
    private let now: @Sendable () -> Date
    private var localMetadata: [LocalThreadMetadataKey: LocalThreadMetadata] = [:]

    init(
        registry: HostRegistry,
        streamClient: any ThreadCardStreamConnecting,
        metadataStore: any LocalThreadMetadataStoring,
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        self.hosts = registry.hosts
        self.streamClient = streamClient
        self.metadataEngine = LocalMetadataEngine(store: metadataStore, now: now)
        self.now = now
    }

    func updateRegistry(_ registry: HostRegistry) {
        hosts = registry.hosts
    }

    func loadSnapshot() async -> ArchiveSnapshot {
        do {
            localMetadata = try await metadataEngine.load()
            DockLog.persistence.debug("archive metadata loaded entries=\(self.localMetadata.count, privacy: .public)")
        } catch {
            localMetadata = [:]
            await metadataEngine.replace(localMetadata)
            DockLog.persistence.warning("archive metadata load failed error=\(DockLog.errorSummary(error), privacy: .public)")
        }

        let results = await loadAllHosts()
        let resolver = hostIdentityResolver(results: results)
        await migrateMetadataHostAliases(using: resolver)
        return makeSnapshot(results: results, resolver: resolver)
    }

    private func loadAllHosts() async -> [ThreadCardHostLoadOutcome] {
        await ThreadCardHostSnapshotLoader(
            streamClient: streamClient,
            expectedView: .archive,
            operation: "archive"
        ).loadAll(hosts: hosts)
    }

    private func makeSnapshot(
        results: [ThreadCardHostLoadOutcome],
        resolver: DockHostIdentityResolver
    ) -> ArchiveSnapshot {
        var cardBatches: [(hostID: String, cards: [DockThreadCardDTO])] = []
        var hostStates: [DockHostStateViewModel] = []

        for outcome in results {
            let host = DockHostViewModel(host: outcome.host)
            switch outcome.result {
            case .success(let collection):
                cardBatches.append((hostID: outcome.host.id, cards: collection.cards))
                hostStates.append(
                    DockHostStateViewModel(
                        host: host,
                        status: collection.hostLoadStatus
                    )
                )
            case .failure(let failure):
                switch failure {
                case .offline(let message):
                    hostStates.append(DockHostStateViewModel(host: host, status: .offline(message)))
                case .error(let message):
                    hostStates.append(DockHostStateViewModel(host: host, status: .error(message)))
                }
            }
        }

        let sections = ArchiveThreadCardProjector(
            hosts: hosts,
            hostIdentityResolver: resolver,
            localMetadata: localMetadata,
            now: now
        ).sections(from: cardBatches)

        return ArchiveSnapshot(
            hosts: hosts.map(DockHostViewModel.init),
            hostStates: hostStates,
            hostIdentityResolver: resolver,
            sections: sections
        )
    }

    private func hostIdentityResolver(results: [ThreadCardHostLoadOutcome]) -> DockHostIdentityResolver {
        let statuses = Dictionary(
            uniqueKeysWithValues: results.map { outcome in
                let status: DockHostLoadStatus
                switch outcome.result {
                case .success(let collection):
                    status = collection.hostLoadStatus
                case .failure(let failure):
                    switch failure {
                    case .offline(let message):
                        status = .offline(message)
                    case .error(let message):
                        status = .error(message)
                    }
                }
                return (outcome.host.id, status)
            }
        )
        return DockHostIdentityResolver(
            hosts: hosts,
            observations: results.flatMap { outcome in
                guard case .success(let collection) = outcome.result else {
                    return [DockHostIdentityObservation]()
                }
                return collection.hosts.map {
                    DockHostIdentityObservation(configuredHostID: outcome.host.id, streamHost: $0)
                } + collection.cards.map {
                    DockHostIdentityObservation(configuredHostID: outcome.host.id, card: $0)
                }
            },
            hostStatuses: statuses
        )
    }

    private func migrateMetadataHostAliases(using resolver: DockHostIdentityResolver) async {
        do {
            localMetadata = try await metadataEngine.migrateHostAliases(using: resolver)
        } catch {
            DockLog.persistence.warning("archive metadata host alias migration failed error=\(DockLog.errorSummary(error), privacy: .public)")
        }
    }

}

import Foundation

public struct DockRelayEndpoint: Codable, Equatable, Sendable, Identifiable {
    public let host: String
    public let port: Int

    public var id: String { serializedEndpoint }

    public var serializedEndpoint: String {
        "\(serializedHost):\(port)"
    }

    public var displayEndpoint: String {
        serializedEndpoint
    }

    public var webSocketURL: URL {
        // URL is transport-only. App config and persistence stay host+port.
        URL(string: "ws://\(serializedEndpoint)")!
    }

    public var statusURL: URL {
        URL(string: "http://\(serializedEndpoint)/statusz")!
    }

    private var serializedHost: String {
        host.contains(":") ? "[\(host)]" : host
    }

    public init(host rawHost: String, port: Int) throws {
        let host = try Self.normalizedHost(rawHost)
        guard (1...CodexDockConstants.Ports.maximumTCPPort).contains(port) else {
            throw DockHostConfigurationError.invalidPort(String(port))
        }
        self.host = host
        self.port = port
    }

    public static func parse(_ rawValue: String) throws -> DockRelayEndpoint {
        let value = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !value.isEmpty else {
            throw DockHostConfigurationError.missingEndpoint
        }

        let host: String
        let portText: String
        if value.hasPrefix("[") {
            guard let closeIndex = value.firstIndex(of: "]") else {
                throw DockHostConfigurationError.invalidEndpoint(value)
            }
            let afterClose = value.index(after: closeIndex)
            guard afterClose < value.endIndex, value[afterClose] == ":" else {
                throw DockHostConfigurationError.invalidEndpoint(value)
            }
            host = String(value[value.index(after: value.startIndex)..<closeIndex])
            portText = String(value[value.index(after: afterClose)...])
        } else {
            let parts = value.split(separator: ":", omittingEmptySubsequences: false)
            guard parts.count == 2 else {
                throw DockHostConfigurationError.invalidEndpoint(value)
            }
            host = String(parts[0])
            portText = String(parts[1])
        }

        guard let port = Int(portText) else {
            throw DockHostConfigurationError.invalidPort(portText)
        }
        return try DockRelayEndpoint(host: host, port: port)
    }

    public static func parseList(_ rawValue: String?) throws -> [DockRelayEndpoint] {
        let endpoints = rawValue?
            .split(separator: ",")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty } ?? []
        guard !endpoints.isEmpty else {
            throw DockHostConfigurationError.missingEndpoint
        }

        var seen: Set<String> = []
        return try endpoints.map { value in
            let endpoint = try DockRelayEndpoint.parse(value)
            guard seen.insert(endpoint.id).inserted else {
                throw DockHostConfigurationError.duplicateHostID(endpoint.id)
            }
            return endpoint
        }
    }

    public func validateAppFacingRelayEndpoint() throws {
        if port == CodexDockConstants.Ports.rawAppServer {
            throw DockHostConfigurationError.rawAppServerEndpoint(displayEndpoint)
        }
    }

    private static func normalizedHost(_ rawHost: String) throws -> String {
        var host = rawHost.trimmingCharacters(in: .whitespacesAndNewlines)
        if host.hasPrefix("[") && host.hasSuffix("]") {
            host.removeFirst()
            host.removeLast()
        }
        while host.hasSuffix(".") {
            host.removeLast()
        }

        guard !host.isEmpty,
              !host.contains("://"),
              !host.contains("/"),
              !host.contains("?"),
              !host.contains("#"),
              !host.contains("@"),
              host.rangeOfCharacter(from: .whitespacesAndNewlines) == nil
        else {
            throw DockHostConfigurationError.invalidHost(rawHost)
        }
        return host
    }
}

public enum DockHostDisplayNameResolver {
    public static func displayName(for endpoint: DockRelayEndpoint) -> String {
        displayName(forHost: endpoint.host)
    }

    public static func displayName(forHost rawHost: String) -> String {
        let host = rawHost.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !host.isEmpty, !isIPAddress(host) else {
            return host
        }

        let stripped = strippingKnownSuffixes(from: host)
        return stripped
            .split(separator: "-")
            .map(capitalizedToken)
            .joined(separator: "-")
    }

    private static func strippingKnownSuffixes(from host: String) -> String {
        var value = host
        for suffix in [".fairy-salmon.ts.net", ".local"] {
            if value.lowercased().hasSuffix(suffix) {
                value.removeLast(suffix.count)
                break
            }
        }
        return value
    }

    private static func capitalizedToken(_ token: Substring) -> String {
        let value = String(token)
        guard let first = value.first else {
            return value
        }
        return first.uppercased() + value.dropFirst()
    }

    private static func isIPAddress(_ host: String) -> Bool {
        host.allSatisfy { character in
            character.isNumber || character == "." || character == ":"
        }
    }
}

public struct DockHostConfiguration: Equatable, Sendable, Identifiable {
    public let endpoint: DockRelayEndpoint

    public var id: String { endpoint.id }
    public var displayName: String { DockHostDisplayNameResolver.displayName(for: endpoint) }
    public var webSocketURL: URL { endpoint.webSocketURL }

    public init(endpoint: DockRelayEndpoint) {
        self.endpoint = endpoint
    }

    public init(host: String, port: Int) throws {
        self.endpoint = try DockRelayEndpoint(host: host, port: port)
    }
}

public enum DockHostConfigurationError: Error, Equatable, LocalizedError, Sendable {
    case missingEndpoint
    case invalidEndpoint(String)
    case invalidHost(String)
    case invalidPort(String)
    case duplicateHostID(String)
    case multipleHostsForSingleConfiguration(String)
    case rawAppServerEndpoint(String)

    public var errorDescription: String? {
        switch self {
        case .missingEndpoint:
            return "Set CODEX_DOCK_HOSTS to one or more relay hosts like 192.168.50.117:\(CodexDockConstants.Ports.dockRelay)."
        case let .invalidEndpoint(value):
            return "Codex Dock relay endpoint must be host:port with no scheme, path, query, username, or password: \(value)"
        case let .invalidHost(value):
            return "Codex Dock relay host must not include a scheme, path, query, username, password, or whitespace: \(value)"
        case let .invalidPort(value):
            return "Codex Dock relay port must be an integer from 1 to 65535: \(value)"
        case let .duplicateHostID(hostID):
            return "CODEX_DOCK_HOSTS must not include the same endpoint more than once: \(hostID)"
        case let .multipleHostsForSingleConfiguration(value):
            return "Use HostRegistry.fromEnvironment for multiple CODEX_DOCK_HOSTS entries; a single host configuration can only use one host: \(value)"
        case let .rawAppServerEndpoint(value):
            return "Codex Dock app-facing hosts must point at the Dock relay on :\(CodexDockConstants.Ports.dockRelay), not the raw Codex app-server on :\(CodexDockConstants.Ports.rawAppServer): \(value)"
        }
    }
}

public extension DockHostConfiguration {
    static func fromEnvironment(
        _ environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> DockHostConfiguration {
        let endpoints = try DockRelayEndpoint.parseList(environment["CODEX_DOCK_HOSTS"])
        try endpoints.forEach { try $0.validateAppFacingRelayEndpoint() }
        guard let endpoint = endpoints.first, endpoints.count == 1 else {
            throw DockHostConfigurationError.multipleHostsForSingleConfiguration(
                endpoints.map(\.id).joined(separator: ",")
            )
        }
        let configuration = DockHostConfiguration(endpoint: endpoint)
        DockLog.hostConfiguration.notice("host configuration loaded host_id=\(configuration.id, privacy: .public) endpoint=\(DockLog.endpoint(configuration.webSocketURL), privacy: .public)")
        return configuration
    }
}

import Foundation

public struct HostRegistry: Equatable, Sendable {
    public let hosts: [DockHostConfiguration]

    public init(hosts: [DockHostConfiguration]) throws {
        guard !hosts.isEmpty else {
            DockLog.hostConfiguration.error("host registry creation failed reason=no_hosts")
            throw DockHostConfigurationError.missingEndpoint
        }
        var seenHostIDs: Set<String> = []
        for host in hosts {
            guard seenHostIDs.insert(host.id).inserted else {
                DockLog.hostConfiguration.error("host registry creation failed reason=duplicate_endpoint endpoint=\(host.id, privacy: .public)")
                throw DockHostConfigurationError.duplicateHostID(host.id)
            }
        }
        self.hosts = hosts
        DockLog.hostConfiguration.notice("host registry created hosts=\(hosts.count, privacy: .public)")
    }
}

public extension HostRegistry {
    static func fromEnvironment(
        _ environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> HostRegistry {
        let endpoints = try DockRelayEndpoint.parseList(environment["CODEX_DOCK_HOSTS"])
        try endpoints.forEach { try $0.validateAppFacingRelayEndpoint() }
        let hosts = endpoints.map(DockHostConfiguration.init(endpoint:))
        let registry = try HostRegistry(hosts: hosts)
        DockLog.hostConfiguration.notice("host registry loaded from environment hosts=\(registry.hosts.count, privacy: .public)")
        return registry
    }
}

