  const appServer = await startCanonicalActivityAppServer({ failTurnsFor: new Set(["newer"]) });
  try {
    await withRelay(appServer.url, async ({ config, wsURL }) => {
      await config.relayStateEngine.reconcileDock({ reason: "test" });
